dtsPropsFor.Text:
/** Type scale. `map-title` is the IM Fell English display face used on map surfaces. */
  variant?: "display" | "heading" | "title" | "map-title" | "label" | "body" | "caption";
  /** Semantic color token. Defaults to ink; caption defaults to muted. */
  color?: "ink" | "muted" | "destructive" | "on-accent" | "trail" | "award" | "cavern-ink";
  children?: React.ReactNode;
  className?: string;
  /** Truncate after N lines. */
  numberOfLines?: number;
  testID?: string;
  /** Every other React Native <Text> prop is forwarded unchanged — nesting, font scaling, accessibility, style. */
  accessibilityLabel?: string;

dtsPropsFor.Input:
/** Field label rendered above the control. Required — the label is the accessible name. */
  label: string;
  /** Helper text under the field. */
  hint?: string;
  /** Error message; also switches the border to the destructive token. */
  error?: string;
  value?: string;
  onChangeText?: (text: string) => void;
  placeholder?: string;
  secureTextEntry?: boolean;
  keyboardType?: "default" | "email-address" | "numeric" | "url" | "phone-pad";
  autoCapitalize?: "none" | "sentences" | "words" | "characters";
  multiline?: boolean;
  editable?: boolean;
  className?: string;
  testID?: string;
  /** Every other React Native <TextInput> prop is forwarded unchanged. */
  autoFocus?: boolean;
